const char* p = p;
while (p < limit) {
    uint8_t byte = *reinterpret_cast<const uint8_t*>(p);
    result |= static_cast<uint64_t>(byte & 0x7F) << (7 * (p - p));
    if ((byte & 0x80) == 0) {
        *value = result;
        return p + 1;
    }
    p++;
}
return nullptr;

